def compute(vars):
    gross_property_equipment = vars["v2"]
    if gross_property_equipment == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}}}
    ratio = vars["v1"] / gross_property_equipment
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "ratio": ratio,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"},
        },
    }
